from collections import deque, Counter

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def flood_from_border(grid, color):
    """The set of cells of `color` reachable from the grid border (4-connectivity)."""
    H, W = len(grid), len(grid[0])
    q = deque((i, j) for i in range(H) for j in range(W)
              if grid[i][j] == color and (i in (0, H - 1) or j in (0, W - 1)))
    seen = set(q)
    while q:
        i, j = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            n = (i + di, j + dj)
            if 0 <= n[0] < H and 0 <= n[1] < W and grid[n[0]][n[1]] == color and n not in seen:
                seen.add(n)
                q.append(n)
    return seen

def enclosed_regions(grid, color=None):
    """The connected regions of `color` (default: background) not reachable from the border."""
    if color is None:
        color = background(grid)
    H, W = len(grid), len(grid[0])
    outside = flood_from_border(grid, color)
    rest = {(i, j) for i in range(H) for j in range(W)
            if grid[i][j] == color and (i, j) not in outside}
    regs = []
    while rest:
        c = rest.pop()
        reg = {c}
        q = deque([c])
        while q:
            i, j = q.popleft()
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                n = (i + di, j + dj)
                if n in rest:
                    rest.discard(n)
                    q.append(n)
                    reg.add(n)
        regs.append(reg)
    return regs

def is_solid_rect(reg):
    """True if a set of cells is exactly a filled axis-aligned rectangle."""
    rs = [i for i, j in reg]
    cs = [j for i, j in reg]
    return (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1) == len(reg)

def fill_rect_holes(grid, new=4):
    """Fill every enclosed background region that is a solid rectangle with color `new`."""
    out = [row[:] for row in grid]
    for reg in enclosed_regions(grid):
        if is_solid_rect(reg):
            for i, j in reg:
                out[i][j] = new
    return out
